import React, { useState, useEffect } from 'react';
import { Card, Button, Select, api, Badge } from '../App';

export default function LabelsPage() {
  const [saleNos,   setSaleNos]   = useState([]);
  const [saleNo,    setSaleNo]    = useState('');
  const [preview,   setPreview]   = useState([]);
  const [selected,  setSelected]  = useState(new Set());
  const [loading,   setLoading]   = useState(false);

  useEffect(() => {
    api.get('/import/sale-numbers').then(r => setSaleNos(r.data));
  }, []);

  const loadPreview = async () => {
    if (!saleNo) return;
    setLoading(true);
    try {
      const r = await api.get(`/labels/preview/${saleNo}`);
      setPreview(r.data);
      setSelected(new Set(r.data.map(x => x.id)));
    } catch (e) {
      alert(e.message);
    } finally {
      setLoading(false);
    }
  };

  const toggleSelect = (id) => {
    setSelected(s => {
      const n = new Set(s);
      n.has(id) ? n.delete(id) : n.add(id);
      return n;
    });
  };

  const printLabels = async () => {
    const ids = Array.from(selected);
    if (ids.length === 0) { alert('Select at least one label'); return; }
    try {
      const response = await fetch('/api/labels/generate', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ marking_ids: ids, sale_no: saleNo })
      });
      if (!response.ok) throw new Error('Failed to generate labels');
      const blob = await response.blob();
      const url  = URL.createObjectURL(blob);
      const a    = document.createElement('a');
      a.href     = url;
      a.download = `labels_${saleNo}.pdf`;
      a.click();
      URL.revokeObjectURL(url);
      // Refresh to show updated printed status
      loadPreview();
    } catch (e) {
      alert('Error: ' + e.message);
    }
  };

  const printAll = async () => {
    if (!saleNo) return;
    try {
      const response = await fetch('/api/labels/generate', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ sale_no: saleNo })
      });
      const blob = await response.blob();
      const url  = URL.createObjectURL(blob);
      const a    = document.createElement('a');
      a.href     = url;
      a.download = `labels_all_${saleNo}.pdf`;
      a.click();
      URL.revokeObjectURL(url);
      loadPreview();
    } catch (e) {
      alert('Error: ' + e.message);
    }
  };

  const printedCount  = preview.filter(x => x.label_printed).length;
  const selectedCount = selected.size;

  return (
    <div>
      <h2 style={{ marginBottom:6, color:'#1a3c5e' }}>🏷️ Labels</h2>
      <p style={{ color:'#888', fontSize:13, marginBottom:20 }}>
        Generate and download PDF labels for confirmed markings. Labels print 2 per row, 5 rows per A4 page.
      </p>

      <Card>
        <div style={{ display:'flex', gap:12, alignItems:'flex-end', flexWrap:'wrap' }}>
          <div style={{ minWidth:220 }}>
            <Select
              label="Sale Number"
              value={saleNo}
              onChange={setSaleNo}
              placeholder="Select sale…"
              options={saleNos.map(s => ({ value: s.sale_no, label: s.sale_no }))}
            />
          </div>
          <Button onClick={loadPreview} disabled={!saleNo || loading} style={{ marginBottom:14 }}>
            {loading ? 'Loading…' : '🔍 Load Labels'}
          </Button>
          {preview.length > 0 && (
            <>
              <Button onClick={printLabels} variant="success" disabled={selectedCount===0} style={{ marginBottom:14 }}>
                🖨️ Download Selected ({selectedCount})
              </Button>
              <Button onClick={printAll} variant="warning" style={{ marginBottom:14 }}>
                🖨️ Download All ({preview.length})
              </Button>
            </>
          )}
        </div>

        {preview.length > 0 && (
          <div style={{ display:'flex', gap:16, fontSize:12, color:'#888' }}>
            <span>Total: <b style={{ color:'#1a2533' }}>{preview.length}</b></span>
            <span>Printed: <b style={{ color:'#1a7a4a' }}>{printedCount}</b></span>
            <span>Not printed: <b style={{ color:'#c0392b' }}>{preview.length - printedCount}</b></span>
          </div>
        )}
      </Card>

      {preview.length > 0 && (
        <Card>
          <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:14 }}>
            <h3 style={{ fontSize:15 }}>Label Preview ({preview.length})</h3>
            <div style={{ display:'flex', gap:8 }}>
              <Button size="sm" variant="outline" onClick={() => setSelected(new Set(preview.map(x=>x.id)))}>Select All</Button>
              <Button size="sm" variant="outline" onClick={() => setSelected(new Set())}>Deselect All</Button>
              <Button size="sm" variant="outline" onClick={() => setSelected(new Set(preview.filter(x=>!x.label_printed).map(x=>x.id)))}>
                Select Unprinted
              </Button>
            </div>
          </div>

          <div style={{ display:'flex', flexWrap:'wrap', gap:14 }}>
            {preview.map(label => (
              <div
                key={label.id}
                onClick={() => toggleSelect(label.id)}
                style={{
                  width:260, border: selected.has(label.id) ? '2.5px solid #1a3c5e' : '1.5px solid #e2e8f0',
                  borderRadius:8, overflow:'hidden', cursor:'pointer',
                  boxShadow: selected.has(label.id) ? '0 0 0 3px #dbeafe' : 'none',
                  transition:'all 0.1s', userSelect:'none'
                }}
              >
                {/* Label header bar */}
                <div style={{ background:'#1a3c5e', color:'#fff', padding:'6px 10px', fontSize:11, fontWeight:700 }}>
                  <div style={{ overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>
                    {label.party_name} ({label.party_code})
                  </div>
                </div>
                {/* Label body */}
                <div style={{ padding:'8px 10px', fontSize:12 }}>
                  <div style={{ fontWeight:700, fontSize:13, marginBottom:4 }}>{label.garden}</div>
                  <div style={{ color:'#555', marginBottom:2 }}>
                    Grade: <b>{label.grade}</b>  Mark: <b>{label.mark}</b>
                  </div>
                  <div style={{ color:'#555', marginBottom:2 }}>
                    Bags: {label.bags}  |  Net Wt: {label.net_wt} kg
                  </div>
                  <div style={{ fontSize:16, fontWeight:700, color:'#1a3c5e', marginTop:6 }}>
                    ₹ {label.final_price ? Number(label.final_price).toFixed(2) : '—'}
                  </div>
                </div>
                {/* Status bar */}
                <div style={{ padding:'4px 10px', background:'#f8fafc', borderTop:'1px solid #f0f4f8', display:'flex', justifyContent:'space-between', alignItems:'center' }}>
                  {label.label_printed
                    ? <Badge color="green">✓ Printed</Badge>
                    : <Badge color="yellow">Not printed</Badge>
                  }
                  {selected.has(label.id) && <Badge color="blue">✓ Selected</Badge>}
                </div>
              </div>
            ))}
          </div>
        </Card>
      )}

      {preview.length === 0 && saleNo && !loading && (
        <Card style={{ textAlign:'center', padding:40, color:'#aaa' }}>
          No confirmed markings found for sale {saleNo}. Create markings first.
        </Card>
      )}

      {/* Label format guide */}
      <Card style={{ background:'#f0f8ff' }}>
        <h3 style={{ marginBottom:8, fontSize:14 }}>📐 Label Format</h3>
        <div style={{ fontSize:12, color:'#555', lineHeight:1.8 }}>
          <div>• PDF output · A4 size · 2 columns × 5 rows = 10 labels per page</div>
          <div>• Each label: 3.5" × 2" · Includes party, garden, grade, mark, bags, net wt, price</div>
          <div>• After download, open in any PDF viewer and print at 100% scale</div>
          <div>• Use standard A4 label sheets or cut printed sheets</div>
        </div>
      </Card>
    </div>
  );
}
